examples.code:
MonarchTheme {
    Surface(color = MonarchTheme.colors.bgCanvas) {
        Column(
            modifier = Modifier.padding(MonarchTheme.spacing.space4),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            MonarchText(text = "Hello", style = MonarchTextStyle.Heading)
            MonarchText(text = "Text, surfaces and buttons take their colours from the theme.", color = MonarchTheme.colors.textMuted)
            MonarchButton(text = "Save", onClick = {}, variant = MonarchButtonVariant.Primary)
        }
    }
}

MonarchTheme(
    scheme = MonarchScheme.Dark,
    contrast = MonarchContrast.More,
    accent = MonarchTokens.Accents.atlas,
) {
    MonarchButton(text = "A button in the Atlas accent", onClick = {}, variant = MonarchButtonVariant.Primary)
}

Box(
    modifier = Modifier
        .background(MonarchTheme.colors.bgSubtle, MonarchTheme.shapes.lg)
        .padding(MonarchTheme.spacing.space4),
) {
    Text(text = "Subtle surface", style = MonarchTheme.typography.label, color = MonarchTheme.colors.textMuted)
}

val brand = remember { MonarchBrandTheme.derive("#0A7CFF", ai = "#7C3AED") }
val tokens = MonarchTokens.light.withAccent(brand.accent)
MonarchTheme(tokens = brand.aiAccent?.let(tokens::withAi) ?: tokens) {
    Text(text = "Summarised by AI", color = MonarchTheme.colors.aiStrong)
}
